              )}
            </div>
            <div className="pj-card-b" style={{ paddingTop: 0 }}><CmPush label={'Module 3 audit chain'} nav={nav} bar /></div>
          </div>
        </>
      )}
      {logOpen && <C2CForm config={LOG_FORM} onCancel={() => setLogOpen(false)} onSubmit={logQuestion} />}
      <C2CToast msg={toast} />
    </div>
  );
}

/** A provenance payload summarised for a table cell, never stringified raw. */
function provenanceDetail(payload: Record<string, unknown> | null): string {
  if (!payload || typeof payload !== 'object') return '--';
  const parts: string[] = [];
  const push = (label: string, value: unknown) => {
    if (value == null || value === '') return;
    parts.push(`${label} ${Array.isArray(value) ? value.join(', ') : String(value)}`);
  };
  push('completeness', payload.completeness != null ? `${payload.completeness}%` : null);
  push('missing', Array.isArray(payload.missingInputs) && payload.missingInputs.length ? payload.missingInputs : null);
  push('reason', payload.reason);
  push('note', payload.resolutionNote);
  push('version', payload.versionNumber);
  if (!parts.length) {
    const keys = Object.keys(payload);
    return keys.length ? keys.slice(0, 4).join(', ') : '--';
  }
  return parts.join(' · ');
}

/* ═══════════ CmcModule shell — sub-tab router ═══════════ */

const CMC_SURF: Record<string, React.ComponentType<{ ask: (text: string) => void; nav?: (id: string) => void }>> = {
  overview: CmOverview,
  materials: CmMaterials,
  specs: CmSpecs,
  stability: CmStability,
  batch: CmBatch,
  change: CmChange,
  quality: CmQuality,
  build: CmModule3Build,
  pathway: CmPathway,
};

export function CmcModule({ onAsk, onNav }: SurfaceViewProps) {
  const ask = onAsk;
  const [tab, setTab] = useState('overview');
  /* The Overview's answer-lead offers "Open change simulator" and the Module 3
     build tab is reachable from Overview the same way, so the setter is
     published for those cross-tab jumps. Assigned in an effect rather than
     during render: a render-phase side effect on a global is exactly the kind
     of write React may run twice or discard. */
  useEffect(() => {
    (window as unknown as { __cmSetTab?: (id: string) => void }).__cmSetTab = setTab;
    return () => {
      delete (window as unknown as { __cmSetTab?: (id: string) => void }).__cmSetTab;
    };
  }, []);

  /* AnA's hands on this screen — the surface-action bus (shared registry:
     cmc.open-tab, identity-resolved). The handler drives the SAME setter the
     sub-tab buttons and __cmSetTab drive. The tab list is a static constant,
     so there is deliberately NO loading guard, NO retry, and NO ready signal —
     a not-ready refusal here would be dishonest. The wave-2 limitation
     (pane forms child-local and invisible here) is closed by the ceremony
     channel: the pane forms — spec edits, batch e-sign releases, stability
     registrations — all render through C2CForm, which reports itself, so a
     switch that would unmount a person's half-completed ceremony refuses.
     The human's own tab buttons still carry no guard; AnA acting on someone's
     behalf holds a higher bar than their own hands. */
  useSurfaceActionHandlers('cmc', {
    'cmc.open-tab': (params) => {
      const target = (params.tab ?? '').trim();
      const meta = CMC_NAV.find((n) => n.id === target);
      if (!meta) return { ok: false, reason: `No CMC tab named "${params.tab}".` };
      if (tab === target) return { ok: true, detail: `Already on ${meta.label}` };
      if (ceremonyOpen()) {
        return {
          ok: false,
          reason:
            'A governed form is open on this screen — switching tabs would discard it. ' +
            'Let the person finish or cancel it first.',
        };
      }
      setTab(target);
      return { ok: true, detail: `Opened ${meta.label}` };
    },
  });

  /* ── What AnA is told about this screen ──
     `useAnaChat` forwards a surface's published context to the orchestrator as
     `module_context`, so this is what makes a generic question ("what should I
     do next?") answerable here without the user restating their situation. The
     shell alone knows only that the surface is "cmc" — not which of the twelve
     sub-tabs is open, nor what is on it.

     Readiness is READ, never assembled: GET /api/cmc/module3-os/readiness is the
     same endpoint the build board renders, so AnA and the board cannot disagree.
     While that fetch is loading or errored the facts are simply ABSENT — telling
     her a percentage nobody measured would make her confidently wrong, which is
     the failure this channel is most able to cause.

     Per surfaceContext's own budget rule: the nouns and numbers a user could
     point at, never raw API bodies, and never anything the screen is hiding. */
  const anaProjectId = cmcProjectId();
  const anaReadiness = useLiveData<{
    totalSections: number; approvedSections: number; staleSections: number;
    openCriticalContradictions: number; exportReady: boolean;
  }>(anaProjectId ? '/api/cmc/module3-os/readiness/' + encodeURIComponent(anaProjectId) : null);
  const tabLabel = CMC_NAV.find((n) => n.id === tab)?.label ?? 'Overview';
  const r = anaReadiness.loading || anaReadiness.error ? null : anaReadiness.data;
  const anaContext = React.useMemo(
    () => ({
      summary:
        `The user is on the ${tabLabel} tab of the CMC Module 3 operating system` +
        (r
          ? `. ${r.approvedSections} of ${r.totalSections} §3.2 sections are approved` +
            (r.staleSections ? `, ${r.staleSections} went stale after approval` : '') +
            (r.openCriticalContradictions ? `, ${r.openCriticalContradictions} critical contradiction(s) are unresolved` : '') +
            `. Final export ${r.exportReady ? 'would pass' : 'is blocked'}.`
          : '.'),
      facts: {
        tab,
        tabLabel,
        /* Spread only once measured, so a fact is never a guess. */
        ...(r
          ? {
              sectionsApproved: r.approvedSections,
              sectionsTotal: r.totalSections,
              staleSections: r.staleSections,
              openCriticalContradictions: r.openCriticalContradictions,
              exportReady: r.exportReady,
            }
          : {}),
      },
      /* Her vocabulary for "drive this screen" requests: the tabs by name, plus
         the governed actions this module actually performs. */
      availableActions: [
        ...CMC_NAV.map((n) => `open the ${n.label} tab`),
        'compile Module 3 from the canonical sources',
        'run the contradiction sweep',
        'check the final-export gate',
        'run the ICH compliance check',
        'generate the control strategy',
        'estimate shelf life from the recorded stability results (ICH Q1E)',
        'assess whether stability batches are combinable (ICH Q1E ANCOVA poolability)',
      ],
    }),
    [tab, tabLabel, r?.totalSections, r?.approvedSections, r?.staleSections, r?.openCriticalContradictions, r?.exportReady],
  );
  usePublishSurfaceContext('cmc', anaContext);

  const Surf = CMC_SURF[tab] || CmOverview;
  return (
    <div className="cm">
      <div className="cm-sub">
        {CMC_NAV.map((n) => (<button key={n.id} className="cm-subtab" data-on={tab === n.id || undefined} onClick={() => setTab(n.id)}>{I[n.icon] || I.grid}{n.label}</button>))}
      </div>
      <CmConnectBar nav={onNav} />
      <Surf ask={ask} nav={onNav} />
    </div>
  );
}

/**
 * Quality by design — CQAs, CPPs, the control strategy, and the ICH check.
 *
 * ── What this binds ───────────────────────────────────────────────────────────
 * Three deterministic, project-data-driven services existed server-side with no
 * caller in this UI at all:
 *
 *   GET  /api/cmc/quality/qbd/:projectId   CQAs and CPPs derived from the
 *                                          project's own specifications,
 *                                          methods, impurity profiles, stability
 *                                          and process records — not from
 *                                          drug-type heuristics
 *   POST /api/cmc/control-strategy         an ICH Q8/Q9/Q10/Q11 control strategy
 *                                          built from those CQAs and the methods
 *                                          that actually control them
 *   POST /api/cmc/ich-compliance           a rule-based check across
 *                                          Q1A/Q2/Q3A-B/Q3D/Q6A-B/Q8/Q9/Q10,
 *                                          every finding citing its guideline
 *
 * The Overview tab has been suggesting "Run the ICH compliance check and show
 * every gap" and "Generate the drug-substance control strategy" as prompts to
 * an assistant, while the endpoints that answer both questions deterministically
 * sat unreachable.
 *
 * ── The honesty these services demand of their UI ─────────────────────────────
 * All three distinguish "we checked and found nothing" from "we could not
 * check". `IchComplianceReport.overallStatus` has an `incomplete` value and
 * `CheckStatus` has `not_evaluated`; `QbdAnalysisResult` carries `partial` and
 * `unevaluatedInputs`; `StabilityMonitoringPlan.derivedFrom` says whether the
 * conditions are the project's or an ICH template. Every one of those is
 * surfaced here. A compliance screen that renders "could not check" as a green
 * tick is worse than no compliance screen.
 */

import React from 'react';
import { I } from '../icons';
import { apiRequest } from '@/lib/queryClient';
import { EmptyState, useLiveData } from '../dataConnect';
import { renderSafeMarkdown } from '../../components/ana/renderSafeMarkdown';
import { useAuthoringHandoff, openSavedAuthoring } from '../authoringHandoff';
import { AuthoringHandoffNotice } from '../AuthoringHandoffNotice';
import { cmcProjectUuid, cmcWriteError } from './cmcShared';
import { openProgramAction } from '../programAction';
import { C2CToast, useToast } from '../toast';

/* ── Read models (mirrors of the service types) ──────────────────────────── */

interface CqaItem {
  name: string;
  source: string;
  materialType?: string;
  evidenceDetail?: string;
  ichBasis: string[];
  methodLinked: boolean;
}

interface CppItem {
  name: string;
  processStep?: string;
  acceptableRange?: string;
  impacts?: string[];
  ichBasis: string[];
  source: string;
}

interface QbdResult {
  cqas: CqaItem[];
  cpps: CppItem[];
  inputs: {
    specificationCount: number;
    methodCount: number;
    stabilityStudyCount: number;
    drugSubstanceCount: number;
    processCount: number;
    cmcSourceObjectCount: number;
  };
  unevaluatedInputs: Array<{ input: string; reason: string }>;
  partial: boolean;
  gaps: string[];
  analyzedAt: string;
}

interface IchFinding {
  guideline: string;
  ruleId: string;
  status: 'pass' | 'warning' | 'fail' | 'not_applicable' | 'not_evaluated';
  message: string;
  evidence: string[];
  citation: string;
}

interface IchReport {
  overallStatus: 'compliant' | 'warnings' | 'non_compliant' | 'incomplete';
  guidelineStatus: Record<string, string>;
  findings: IchFinding[];
  counts: { pass: number; warning: number; fail: number; not_applicable: number; not_evaluated: number };
  unevaluatedInputs: Array<{ input: string; reason: string }>;
  evaluatedAt: string;
}

interface ControlElement {
  controlType: string;
  description: string;
  targetCqa?: string;
  acceptanceCriterion?: string;
  performedBy?: string;
  ichBasis: string[];
  justification: string;
}

interface StabilityMonitoringPlan {
  longTermCondition: string;
  acceleratedCondition: string;
  testParameters: string[];
  timePoints: string[];
  ichBasis: string[];
  derivedFrom: 'project_data' | 'ich_default' | 'not_evaluated';
  note?: string;
}

interface ControlStrategy {
  scope: string;
  cqas: CqaItem[];
  cpps: CppItem[];
  controlElements: ControlElement[];
  stabilityMonitoring: StabilityMonitoringPlan;
  gaps: string[];
  citations: string[];
  generatedAt: string;
}

/* ── Vocabulary ──────────────────────────────────────────────────────────── */

const FINDING_TONE: Record<string, string> = {
  pass: 'ok',
  warning: 'warn',
  fail: 'err',
  not_applicable: 'dim',
  /* Deliberately warn, not dim: "we could not check this" is an open question,
     not a settled non-issue, and must not read like one. */
  not_evaluated: 'warn',
};

const OVERALL_LABEL: Record<string, { tone: string; text: string }> = {
  compliant: { tone: 'ok', text: 'compliant' },
  warnings: { tone: 'warn', text: 'compliant with warnings' },
  non_compliant: { tone: 'err', text: 'non-compliant' },
  incomplete: { tone: 'warn', text: 'incomplete — some checks could not run' },
};

const CONTROL_TYPE_LABEL: Record<string, string> = {
  release_test: 'Release test',
  in_process_control: 'In-process control',
  stability_monitoring: 'Stability monitoring',
  raw_material_test: 'Raw material test',
  process_parameter_range: 'Process parameter range',
};

/* ── The surface ─────────────────────────────────────────────────────────── */

export function CmQuality({ ask, nav }: { ask: (text: string) => void; nav?: (id: string) => void }) {
  const handoff = useAuthoringHandoff();
  const saveToAuthoring = handoff.save;
  const projectId = cmcProjectUuid();
  const qbd = useLiveData<QbdResult>(
    projectId ? '/api/cmc/quality/qbd/' + encodeURIComponent(projectId) : null,
  );
  const [toast, fireToast] = useToast();
  const [busy, setBusy] = React.useState<string | null>(null);
  const [ich, setIch] = React.useState<IchReport | null>(null);
  const [strategy, setStrategy] = React.useState<ControlStrategy | null>(null);
  const [scope, setScope] = React.useState<'both' | 'drug_substance' | 'drug_product'>('both');
  const savingDoc = handoff.state?.phase === 'pending';

  const post = async <T,>(key: string, path: string, body: unknown): Promise<T | null> => {
    if (busy) return null;
    setBusy(key);
    try {
      const res = await apiRequest('POST', path, body);
      const json = await res.json().catch(() => null);
      if (!res.ok) {
        fireToast(cmcWriteError(json, res.status), 'error');
        return null;
      }
      return ((json as { data?: T })?.data ?? null) as T | null;
    } catch (e) {
      fireToast(e instanceof Error ? e.message : String(e), 'error');
      return null;
    } finally {
      setBusy(null);
    }
  };

  const runIch = async () => {
    if (!projectId) return;
    const report = await post<IchReport>('ich', '/api/cmc/ich-compliance', { projectId });
    if (report) {
      setIch(report);
      const blocking = report.counts.fail;
      fireToast(
        blocking
          ? `ICH check complete — ${blocking} ${blocking === 1 ? 'deficiency' : 'deficiencies'}, ${report.counts.warning} warnings.`
          : `ICH check complete — no deficiencies, ${report.counts.warning} warnings, ${report.counts.not_evaluated} not evaluated.`,
      );
    }
  };

  const runStrategy = async () => {
    if (!projectId) return;
    const doc = await post<ControlStrategy>('strategy', '/api/cmc/control-strategy', { projectId, scope });
    if (doc) {
      setStrategy(doc);
      fireToast(`Control strategy generated — ${doc.controlElements.length} control elements over ${doc.cqas.length} CQAs.`);
    }
  };

  /* The generated strategy is Module 3 quality documentation, so "open in
     editor" CREATES it: the document and the section carrying the markdown are
     both POSTed, and navigation happens only on a clean write. See
     ../authoringHandoff. */
  const openStrategyInEditor = async () => {
    if (!strategy || handoff.blocked) return;
      const res = await saveToAuthoring({
        title: 'CMC Control Strategy',
        module: 'M3',
        code: 'cmc_control_strategy',
        content: strategyMarkdown(strategy),
        subject: 'the control strategy',
      });
      if (!res.isCurrent()) return;
      if (!res.ok) { fireToast(res.message, 'error'); return; }
      if (nav) openSavedAuthoring(res, nav);
      else fireToast(res.message);
  };

  if (!projectId) {
    return (
      <div className="cm-body">
        <Head ask={ask} />
        <div className="pj-card">
          <div className="pj-card-b">
            <EmptyState
              icon={I.sigma}
              title="Open a program to analyse its quality design"
              hint="CQAs, CPPs, the control strategy and the ICH check are all derived from one project's own specifications, methods, impurity profiles, stability and process records."
              action={openProgramAction(nav)}
              regulation="Serves the quality design record (ICH Q8, Q9 and Q10)"
            />
          </div>
        </div>
      </div>
    );
  }

  const result = qbd.data;

  return (
    <div className="cm-body">
      <Head
        ask={ask}
        actions={
          <>
            <button className="nda-open" onClick={() => void runIch()} disabled={Boolean(busy)}>
              {I.shieldCheck} {busy === 'ich' ? 'Checking…' : 'Run ICH compliance check'}
            </button>
            <button className="reg-cta" onClick={() => void runStrategy()} disabled={Boolean(busy)}>
              {I.workflow} {busy === 'strategy' ? 'Generating…' : 'Generate control strategy'}
            </button>
            {/* Both buttons report their work by swapping their own label — and
                disable themselves at the same moment. A disabled control is
                removed from the tab order and its label change is not reliably
                announced, so pressing either one went quiet exactly while it
                ran. The status is stated outside the control that is busy. */}
            <span className="sr-only" role="status" aria-live="polite">
              {busy === 'ich'
                ? 'Running the ICH compliance check…'
                : busy === 'strategy'
                  ? 'Generating the control strategy…'
                  : ''}
            </span>
          </>
        }
      />

      {/* ── CQAs / CPPs ── */}
      {qbd.loading ? (
        <EmptyState icon={I.sigma} title="Deriving CQAs and CPPs from this project’s data…" busy testId="cmc-qbd-loading" />
      ) : qbd.error ? (
        <EmptyState
          tone="error"
          icon={I.alertTriangle}
          title="Couldn’t derive the quality attributes"
          hint={`The QbD register didn’t respond (${qbd.error}). It reads this project's specifications, methods, impurity profiles, stability and process records.`}
        />
      ) : result ? (
        <>
          <div className="cm-kpis">
            <Kpi l="CQAs derived" v={result.cqas.length} s="ICH Q8" />
            <Kpi l="Controlled by a method" v={result.cqas.filter((c) => c.methodLinked).length} tone={result.cqas.length && result.cqas.every((c) => c.methodLinked) ? 'ok' : 'warn'} />
            <Kpi l="CPPs derived" v={result.cpps.length} s="ICH Q11" />
            <Kpi l="Specifications read" v={result.inputs.specificationCount} />
            <Kpi l="Methods read" v={result.inputs.methodCount} />
            <Kpi l="Gaps" v={result.gaps.length} tone={result.gaps.length ? 'warn' : 'ok'} />
          </div>

          {result.partial && (
            <div className="pj-con" style={{ marginBottom: 14 }}>
              <span className="ico">{I.alertTriangle}</span>
              <div>
                <div className="pj-con-t">This analysis is partial</div>
                <div className="pj-con-d">
                  {result.unevaluatedInputs.map((u) => `${u.input} (${u.reason})`).join('; ')}. Attributes derived
                  from those inputs are missing from the lists below, and their absence is not evidence that they
                  do not exist.
                </div>
              </div>
            </div>
          )}

          {result.gaps.length > 0 && (
            <div className="pj-con" style={{ marginBottom: 14 }}>
              <span className="ico">{I.info}</span>
              <div>
                <div className="pj-con-t">{result.gaps.length} {result.gaps.length === 1 ? 'gap' : 'gaps'} in the quality design</div>
                <div className="pj-con-d"><ul className="cm-list">{result.gaps.map((g, i) => <li key={i}>{g}</li>)}</ul></div>
              </div>
            </div>
          )}

          <div className="pj-card" style={{ marginBottom: 16 }}>
            <div className="pj-card-h">
              <span className="t">Critical quality attributes</span>
              <span className="s">derived from this project’s records — ICH Q8(R2)</span>
            </div>
            <div className="pj-card-b" style={{ padding: 0 }}>
              {result.cqas.length === 0 ? (
                <div style={{ padding: 12 }}>
                  <EmptyState
                    icon={I.sigma}
                    title="No CQAs could be derived yet"
                    hint="CQAs are inferred from recorded specifications, impurity profiles, stability-indicating parameters and method purposes. Record those and they appear here — nothing is inferred from the drug type alone."
                  />
                </div>
              ) : (
                <table className="reg-tbl">
                  <thead><tr><th>Attribute</th><th>Material</th><th>Derived from</th><th>Evidence</th><th>ICH basis</th><th>Method</th></tr></thead>
                  <tbody>
                    {result.cqas.map((c, i) => (
                      <tr key={i}>
                        <td style={{ fontWeight: 600 }}>{c.name}</td>
                        <td>{c.materialType || '--'}</td>
                        <td>{c.source.replace(/_/g, ' ')}</td>
                        <td>{c.evidenceDetail || '--'}</td>
                        <td className="mono">{c.ichBasis.join(', ') || '--'}</td>
                        <td>
                          <span className={'rd-chip tone-' + (c.methodLinked ? 'ok' : 'warn')}>
                            {c.methodLinked ? 'controlled' : 'no method'}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>

          <div className="pj-card" style={{ marginBottom: 16 }}>
            <div className="pj-card-h">
