                            ['PRR', fmt(scrRes.prr)],
                            ['ROR (95% CI)', `${fmt(scrRes.ror)} (${fmt(scrRes.rorCi?.lower)}–${fmt(scrRes.rorCi?.upper)})`],
                            ['Chi-squared (Yates)', fmt(scrRes.chiSquared)],
                            ['EBGM', fmt(scrRes.ebgm)],
